// Request (Streamable HTTP — both Accept types are required)
POST /mcp
Accept: application/json, text/event-stream
Content-Type: application/json

{"jsonrpc":"2.0","id":1,"method":"initialize","params":{
  "protocolVersion":"2026-07-28","capabilities":{},
  "clientInfo":{"name":"agent-lighthouse","version":"1.0.0"}}}

// Response — capabilities are negotiated here, not in a static file
{"jsonrpc":"2.0","id":1,"result":{
  "protocolVersion":"2026-07-28",
  "serverInfo":{"name":"your-server","version":"1.0.0"},
  "capabilities":{"tools":{},"resources":{}}}}

// tools/list — every tool should carry a boolean readOnlyHint
{"jsonrpc":"2.0","id":2,"result":{"tools":[
  {"name":"searchProducts","annotations":{"readOnlyHint":true}},
  {"name":"addToCart","annotations":{"readOnlyHint":false,"destructiveHint":false}}]}}

POST /mcp HTTP/1.1
Content-Type: application/json
Accept: application/json, text/event-stream
MCP-Protocol-Version: 2026-07-28

{"jsonrpc":"2.0","id":"1","method":"server/discover","params":{"_meta":{
  "io.modelcontextprotocol/protocolVersion":"2026-07-28",
  "io.modelcontextprotocol/clientInfo":{"name":"acme-agent","version":"1.0.0"},
  "io.modelcontextprotocol/clientCapabilities":{}}}}

// 200 — the DiscoverResult is what a client reads before any consent prompt
{"jsonrpc":"2.0","id":"1","result":{
  "supportedVersions":["2025-11-25","2026-07-28"],
  "capabilities":{"tools":{},"resources":{}},
  "instructions":"Call searchProducts before addToCart.",
  "serverInfo":{"name":"acme-shop","version":"2.1.0"}}}

// GET and DELETE on the same path answer 405 — there is no session to resume
// and no stream to open in the current transport.

HTTP/1.1 401 Unauthorized
WWW-Authenticate: Bearer resource_metadata="https://api.example.com/.well-known/oauth-protected-resource/mcp", scope="mcp:tools"

// GET https://api.example.com/.well-known/oauth-protected-resource/mcp
{
  "resource": "https://api.example.com/mcp",
  "resource_name": "Acme MCP",
  "authorization_servers": ["https://auth.example.com"],
  "scopes_supported": ["mcp:tools", "mcp:resources"],
  "bearer_methods_supported": ["header"]
}

// GET https://auth.example.com/.well-known/oauth-authorization-server
{
  "issuer": "https://auth.example.com",
  "authorization_endpoint": "https://auth.example.com/authorize",
  "token_endpoint": "https://auth.example.com/token",
  "code_challenge_methods_supported": ["S256"],
  "authorization_response_iss_parameter_supported": true
}

{"jsonrpc":"2.0","id":2,"result":{"tools":[{
  "name": "searchProducts",
  "description": "Search the catalogue.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "query":  { "type": "string" },
      "locale": { "type": "string", "x-mcp-header": "Accept-Language" }
    },
    "required": ["query"]
  },
  "outputSchema": { "type": "object", "properties": { "results": { "type": "array" } } }
}]}}

// x-mcp-header rules, all statically checkable:
//   value is a non-empty RFC 9110 token — no space, no CR/LF, no ":"
//   values are unique case-insensitively within one inputSchema
//   the annotated property is type string, integer or boolean — never number
//   the path to it is properties-only: no items, oneOf, allOf, $ref hop

{
  "name": "create_reservation",
  "title": "Create a reservation",
  "description": "Book a stay for a guest at a property, at a chosen rate plan.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "property_id": { "type": "string", "description": "The property to book, as returned by search_properties." },
      "rate_plan":   { "type": "string", "description": "Which rate the booking uses.", "enum": ["FLEX", "NREF", "CORP", "GRP"] },
      "line_items":  {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "tax_code": { "type": "string", "description": "Jurisdiction tax code applied to this line." }
          }
        }
      }
    },
    "required": ["property_id", "rate_plan"]
  },
  "outputSchema": { "type": "object", "properties": { "confirmation": { "type": "string" } } }
}

{"jsonrpc":"2.0","id":2,"result":{
  "tools":[ /* stable order, stable key order, every call */ ],
  "resultType":"complete",
  "ttlMs": 300000,
  "cacheScope": "private"
}}

// ttlMs absent means "assume 0" to a client: every access becomes a round-trip.
// cacheScope "public" means the result may be shared across access tokens —
// only correct when the tool list does not depend on who is asking.
// Serialize tools deterministically: same order, same key order, no timestamps,
// no per-request ids inside inputSchema.

// A client one revision ahead sends what it prefers:
POST /mcp
MCP-Protocol-Version: 1900-01-01
{"jsonrpc":"2.0","id":"1","method":"server/discover","params":{"_meta":{
  "io.modelcontextprotocol/protocolVersion":"1900-01-01"}}}

// The only answer that lets it recover — 400, with the list to choose from:
{"jsonrpc":"2.0","id":"1","error":{
  "code":-32022,
  "message":"Unsupported protocol version",
  "data":{"supported":["2025-11-25","2026-07-28"],"requested":"1900-01-01"}}}

// Header and body must agree; when they do not, say so rather than picking one:
{"jsonrpc":"2.0","id":"1","error":{
  "code":-32020,
  "message":"MCP-Protocol-Version header does not match params._meta"}}

