// Ship identifiers, not the rendered body: the HTML already carries it.
export async function getServerSideProps() {
  const article = await getArticle(id);
  return { props: { id: article.id, title: article.title } }; // not article.body
}

// Next.js App Router (server component by default):
export default async function Page() {
  const data = await fetchProducts();
  return <ProductList items={data} />;
}

// Or with getServerSideProps (Pages Router):
export async function getServerSideProps() {
  const data = await fetchProducts();
  return { props: { data } };
}

